export void M_DMaterialIntoPin(inout material m)
{
    material Attributes;
    Attributes.BaseColor = float3(1.0, 0.0, 0.0);
    Attributes.Roughness = 0.5;

    m.BaseColor = float3(1.0, 0.0, 0.0);
    m.Roughness = 0.5;
    m.Opacity = UE.BlendMaterialAttributes(A = Attributes, B = Attributes, Alpha = 0.25).Roughness;
}
